-- Data Mart en estrella. Base dedicada: REC_ECBD_Energia.
-- Regenera únicamente tablas de este proyecto dentro de una transacción.
USE master;
GO
IF DB_ID(N'REC_ECBD_Energia') IS NULL CREATE DATABASE [REC_ECBD_Energia];
GO
USE [REC_ECBD_Energia];
GO
SET NOCOUNT ON;
SET XACT_ABORT ON;
BEGIN TRY
BEGIN TRANSACTION;
IF OBJECT_ID(N'dbo.vDatasetReconstruido', N'V') IS NOT NULL DROP VIEW dbo.vDatasetReconstruido;
IF OBJECT_ID(N'dbo.MatrizConfusion', N'U') IS NOT NULL DROP TABLE dbo.[MatrizConfusion];
IF OBJECT_ID(N'dbo.ImportanciaVariables', N'U') IS NOT NULL DROP TABLE dbo.[ImportanciaVariables];
IF OBJECT_ID(N'dbo.PerfilesClusters', N'U') IS NOT NULL DROP TABLE dbo.[PerfilesClusters];
IF OBJECT_ID(N'dbo.VarianzaPCA', N'U') IS NOT NULL DROP TABLE dbo.[VarianzaPCA];
IF OBJECT_ID(N'dbo.EvaluacionClusters', N'U') IS NOT NULL DROP TABLE dbo.[EvaluacionClusters];
IF OBJECT_ID(N'dbo.MetricasClasificacion', N'U') IS NOT NULL DROP TABLE dbo.[MetricasClasificacion];
IF OBJECT_ID(N'dbo.MetricasRegresion', N'U') IS NOT NULL DROP TABLE dbo.[MetricasRegresion];
IF OBJECT_ID(N'dbo.HECHOS', N'U') IS NOT NULL DROP TABLE dbo.[HECHOS];
IF OBJECT_ID(N'dbo.DimTime', N'U') IS NOT NULL DROP TABLE dbo.[DimTime];
IF OBJECT_ID(N'dbo.DimCluster', N'U') IS NOT NULL DROP TABLE dbo.[DimCluster];
IF OBJECT_ID(N'dbo.DimConjunto', N'U') IS NOT NULL DROP TABLE dbo.[DimConjunto];
IF OBJECT_ID(N'dbo.DimClase', N'U') IS NOT NULL DROP TABLE dbo.[DimClase];
IF OBJECT_ID(N'dbo.DimAcristalamiento', N'U') IS NOT NULL DROP TABLE dbo.[DimAcristalamiento];
IF OBJECT_ID(N'dbo.DimOrientacion', N'U') IS NOT NULL DROP TABLE dbo.[DimOrientacion];
IF OBJECT_ID(N'dbo.DimGeometria', N'U') IS NOT NULL DROP TABLE dbo.[DimGeometria];
IF OBJECT_ID(N'dbo.DatasetOriginal', N'U') IS NOT NULL DROP TABLE dbo.[DatasetOriginal];
IF OBJECT_ID(N'dbo.DimAltura', N'U') IS NOT NULL DROP TABLE dbo.[DimAltura];
IF OBJECT_ID(N'dbo.DimPorcentajeCristal', N'U') IS NOT NULL DROP TABLE dbo.[DimPorcentajeCristal];
IF OBJECT_ID(N'dbo.DimDistribucion', N'U') IS NOT NULL DROP TABLE dbo.[DimDistribucion];
CREATE TABLE dbo.[DatasetOriginal] (
    [id_registro] INT NOT NULL,
    [X1] FLOAT NOT NULL,
    [X2] FLOAT NOT NULL,
    [X3] FLOAT NOT NULL,
    [X4] FLOAT NOT NULL,
    [X5] FLOAT NOT NULL,
    [X6] INT NOT NULL,
    [X7] FLOAT NOT NULL,
    [X8] INT NOT NULL,
    [Y1] FLOAT NOT NULL,
    [Y2] FLOAT NOT NULL,
    CONSTRAINT [PK_DatasetOriginal] PRIMARY KEY ([id_registro])
);
CREATE TABLE dbo.[DimGeometria] (
    [id_geometria] INT NOT NULL,
    [compacidad] FLOAT NOT NULL,
    [superficie] FLOAT NOT NULL,
    [area_pared] FLOAT NOT NULL,
    [area_techo] FLOAT NOT NULL,
    [altura] FLOAT NOT NULL,
    CONSTRAINT [PK_DimGeometria] PRIMARY KEY ([id_geometria])
);
CREATE TABLE dbo.[DimOrientacion] (
    [id_orientacion] INT NOT NULL,
    [orientacion] NVARCHAR(120) NOT NULL,
    CONSTRAINT [PK_DimOrientacion] PRIMARY KEY ([id_orientacion])
);
CREATE TABLE dbo.[DimAcristalamiento] (
    [id_acristalamiento] INT NOT NULL,
    [proporcion_cristal] FLOAT NOT NULL,
    [distribucion_codigo] INT NOT NULL,
    CONSTRAINT [PK_DimAcristalamiento] PRIMARY KEY ([id_acristalamiento])
);
CREATE TABLE dbo.[DimClase] (
    [id_clase] INT NOT NULL,
    [clase] NVARCHAR(120) NOT NULL,
    [regla] NVARCHAR(120) NOT NULL,
    CONSTRAINT [PK_DimClase] PRIMARY KEY ([id_clase])
);
CREATE TABLE dbo.[DimConjunto] (
    [id_conjunto] INT NOT NULL,
    [conjunto] NVARCHAR(120) NOT NULL,
    CONSTRAINT [PK_DimConjunto] PRIMARY KEY ([id_conjunto])
);
CREATE TABLE dbo.[DimCluster] (
    [id_cluster] INT NOT NULL,
    [cluster] NVARCHAR(120) NOT NULL,
    CONSTRAINT [PK_DimCluster] PRIMARY KEY ([id_cluster])
);
CREATE TABLE dbo.[DimTime] (
    [id_tiempo] INT NOT NULL,
    [fecha] NVARCHAR(120) NOT NULL,
    [anio] INT NOT NULL,
    [trimestre] INT NOT NULL,
    [mes_numero] INT NOT NULL,
    [mes_nombre] NVARCHAR(120) NOT NULL,
    [dia] INT NOT NULL,
    [origen] NVARCHAR(120) NOT NULL,
    CONSTRAINT [PK_DimTime] PRIMARY KEY ([id_tiempo])
);
CREATE TABLE dbo.[HECHOS] (
    [id_registro] INT NOT NULL,
    [id_geometria] INT NOT NULL,
    [id_orientacion] INT NOT NULL,
    [id_acristalamiento] INT NOT NULL,
    [id_clase] INT NOT NULL,
    [id_conjunto] INT NOT NULL,
    [id_cluster] INT NOT NULL,
    [id_tiempo] INT NOT NULL,
    [Y1] FLOAT NOT NULL,
    [Y2] FLOAT NOT NULL,
    [Y1_predicha] FLOAT NULL,
    [Y2_predicha] FLOAT NULL,
    [clase_predicha] NVARCHAR(120) NULL,
    [error_absoluto_Y1] FLOAT NULL,
    [error_absoluto_Y2] FLOAT NULL,
    [PC1] FLOAT NOT NULL,
    [PC2] FLOAT NOT NULL,
    CONSTRAINT [PK_HECHOS] PRIMARY KEY ([id_registro]),
    CONSTRAINT [FK_HECHOS_DimGeometria] FOREIGN KEY ([id_geometria]) REFERENCES dbo.[DimGeometria]([id_geometria]),
    CONSTRAINT [FK_HECHOS_DimOrientacion] FOREIGN KEY ([id_orientacion]) REFERENCES dbo.[DimOrientacion]([id_orientacion]),
    CONSTRAINT [FK_HECHOS_DimAcristalamiento] FOREIGN KEY ([id_acristalamiento]) REFERENCES dbo.[DimAcristalamiento]([id_acristalamiento]),
    CONSTRAINT [FK_HECHOS_DimClase] FOREIGN KEY ([id_clase]) REFERENCES dbo.[DimClase]([id_clase]),
    CONSTRAINT [FK_HECHOS_DimConjunto] FOREIGN KEY ([id_conjunto]) REFERENCES dbo.[DimConjunto]([id_conjunto]),
    CONSTRAINT [FK_HECHOS_DimCluster] FOREIGN KEY ([id_cluster]) REFERENCES dbo.[DimCluster]([id_cluster]),
    CONSTRAINT [FK_HECHOS_DimTime] FOREIGN KEY ([id_tiempo]) REFERENCES dbo.[DimTime]([id_tiempo]),
    CONSTRAINT CK_HECHOS_cargas CHECK (Y1 > 0 AND Y2 > 0),
    CONSTRAINT CK_HECHOS_prueba CHECK ((id_conjunto=1 AND Y1_predicha IS NULL AND Y2_predicha IS NULL AND clase_predicha IS NULL) OR (id_conjunto=2 AND Y1_predicha IS NOT NULL AND Y2_predicha IS NOT NULL AND clase_predicha IS NOT NULL))
);
CREATE TABLE dbo.[MetricasRegresion] (
    [modelo] NVARCHAR(120) NOT NULL,
    [objetivo] NVARCHAR(120) NOT NULL,
    [MAE] FLOAT NOT NULL,
    [RMSE] FLOAT NOT NULL,
    [R2] FLOAT NOT NULL
);
CREATE TABLE dbo.[MetricasClasificacion] (
    [modelo] NVARCHAR(120) NOT NULL,
    [accuracy] FLOAT NOT NULL,
    [precision_macro] FLOAT NOT NULL,
    [recall_macro] FLOAT NOT NULL,
    [F1_macro] FLOAT NOT NULL
);
CREATE TABLE dbo.[EvaluacionClusters] (
    [k] INT NOT NULL,
    [inercia] FLOAT NOT NULL,
    [silhouette] FLOAT NOT NULL
);
CREATE TABLE dbo.[VarianzaPCA] (
    [componente] NVARCHAR(120) NOT NULL,
    [varianza_explicada] FLOAT NOT NULL,
    [varianza_acumulada] FLOAT NOT NULL
);
CREATE TABLE dbo.[PerfilesClusters] (
    [id_cluster] INT NOT NULL,
    [registros] INT NOT NULL,
    [compacidad_media] FLOAT NOT NULL,
    [superficie_media] FLOAT NOT NULL,
    [pared_media] FLOAT NOT NULL,
    [techo_medio] FLOAT NOT NULL,
    [altura_media] FLOAT NOT NULL,
    [cristal_medio] FLOAT NOT NULL,
    [calefaccion_media] FLOAT NOT NULL,
    [refrigeracion_media] FLOAT NOT NULL
);
CREATE TABLE dbo.[ImportanciaVariables] (
    [tarea] NVARCHAR(120) NOT NULL,
    [variable] NVARCHAR(120) NOT NULL,
    [importancia_media] FLOAT NOT NULL,
    [desviacion] FLOAT NOT NULL
);
CREATE TABLE dbo.[MatrizConfusion] (
    [clase_real] NVARCHAR(120) NOT NULL,
    [clase_predicha] NVARCHAR(120) NOT NULL,
    [registros] INT NOT NULL
);
COMMIT;
END TRY
BEGIN CATCH
    IF @@TRANCOUNT > 0 ROLLBACK;
    THROW;
END CATCH;
GO
BEGIN TRY
BEGIN TRANSACTION;
IF (SELECT COUNT(*) FROM dbo.HECHOS) <> 768 THROW 51000, 'Conteo incorrecto en HECHOS', 1;
IF (SELECT COUNT(Y1_predicha) FROM dbo.HECHOS) <> 231 THROW 51001, 'Prueba temporal debe tener 231 predicciones', 1;
COMMIT;
END TRY
BEGIN CATCH
    IF @@TRANCOUNT > 0 ROLLBACK;
    THROW;
END CATCH;
GO
CREATE OR ALTER VIEW dbo.vDatasetReconstruido AS
SELECT h.id_registro, g.compacidad X1, g.superficie X2, g.area_pared X3, g.area_techo X4,
       g.altura X5, o.id_orientacion X6, a.proporcion_cristal X7, a.distribucion_codigo X8, h.Y1, h.Y2
FROM dbo.HECHOS h
JOIN dbo.DimGeometria g ON h.id_geometria=g.id_geometria
JOIN dbo.DimOrientacion o ON h.id_orientacion=o.id_orientacion
JOIN dbo.DimAcristalamiento a ON h.id_acristalamiento=a.id_acristalamiento;
GO
SET NOCOUNT ON;
IF EXISTS (SELECT * FROM dbo.DatasetOriginal EXCEPT SELECT * FROM dbo.vDatasetReconstruido)
 OR EXISTS (SELECT * FROM dbo.vDatasetReconstruido EXCEPT SELECT * FROM dbo.DatasetOriginal)
 THROW 51002, 'La reconstruccion difiere del dataset original', 1;
IF (SELECT COUNT(*) FROM sys.foreign_keys WHERE parent_object_id=OBJECT_ID(N'dbo.HECHOS') AND is_disabled=0 AND is_not_trusted=0) <> 7
 THROW 51003, 'HECHOS debe tener siete llaves foraneas activas', 1;
SELECT 'HECHOS' tabla, COUNT(*) filas FROM dbo.HECHOS;
SELECT 'DatasetOriginal' tabla, COUNT(*) filas FROM dbo.DatasetOriginal;
SELECT 'Llaves foraneas activas' control, COUNT(*) valor FROM sys.foreign_keys WHERE is_disabled=0 AND is_not_trusted=0;
SELECT 'Predicciones de prueba' control, COUNT(Y1_predicha) valor FROM dbo.HECHOS;
SELECT AVG(Y1) calefaccion_media, AVG(Y2) refrigeracion_media FROM dbo.HECHOS;
SELECT 'RECONSTRUCCION_EXACTA_OK' resultado;
